"""Review selected flagged constructions through surah al-Tawbah."""
import argparse
from semantic_review import ReviewBatch, validate


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    b = ReviewBatch("semantic-review-005", "Individually read flags through surah 9, distinguishing Turkish restriction idioms, verbal valency, relative complements and time relations.")
    if b.exists:
        validate()
        return
    def p(ayah, identifier, pieces, reason):
        b.phrase(ayah + "-" + identifier, [(text, f"{ayah}:{word}" if word else None) for text, word in pieces], reason)
    def c(ayah, identifier, values, reason):
        b.change(ayah + "-" + identifier, {f"{ayah}:{word}": value for word, value in values.items()}, reason)
    def d(keys, reason, retained=False):
        for key in keys.split(): b.decide(key, reason, retained)
    p("3:28", "scope-of-relation", [("hiçbir ", 0), ("şey", 16), ("de", 15)], "Fi shayin delimits any respect of the relation with Allah. Expose its locative in hiçbir şeyde; do not call fi a lexical word for friendship.")
    c("3:28", "negative-relationship", {12: "[bir bağı] yoktur"}, "Fa-laysa ... min Allahi denies the relationship in any respect. Bracketed bir bağı supplies the understood relation, not an extra source noun.")
    d("3:28:15", "Expose the scope locative, preserving the relational idiom and its stated precaution exception.")
    c("3:30", "pronominal-roles", {17: "kendisiyle", 18: "ve onun [kötülüğün] arasında"}, "Baynaha refers to the soul itself; wa-baynahu refers to the evil just mentioned. The inherited Turkish location assignments had these two pronouns reversed; also restore the conjunction.")
    d("3:30:16", "Retain anna's wish-content function as absorbed by the Turkish keşke olsa construction at law; do not invent a separate nominal ending there. Correct the two adjacent pronominal roles, which were reversed.")
    p("3:75", "persistent-demand", [("başında", 21), (" ", 0), ("sürekli ", 20), ("dur", 22), ("ma", 18), ("dıkça", 19)], "Illa ma dumta alayhi qaiman conditions repayment on persistent standing over the debtor. Turkish başında sürekli durmadıkça naturally combines the exception as negative condition, ma as temporal subordination, dumta as persistence and qaiman as standing. Its negative suffix is functional Turkish realization of the exception, not an Arabic negative verb.")
    d("3:75:19", "Expose the temporal conditional instead of copying sürekli; preserve persistence and the standing-over relation at their source locations.")
    p("3:97", "security-predicate", [("güvende", 9), ("dir", 8)], "Kana aminan under the entry condition predicates security. Güvendedir exposes security and the copula without importing a ceased past state.")
    d("3:97:8", "Restore nominal predication rather than hiding the full güvene erer at kana.")
    p("4:24", "benefit-complement", [("yararlan", 23), ("ma", 22), ("nıza karşılık", 23)], "Fa-ma istamtatum introduces the benefit in the subsequent due-payment clause. Expose its nominal content rather than copying the whole yararlanmanıza karşılık. This preserves the inherited benefit reading and does not settle disputed legal applications of istimta.")
    d("4:24:22", "Restore the nominal content view while preserving the inherited due-payment construction; legal interpretation remains outside this local linguistic decision.")
    p("4:25", "from-possessions", [("o halde ", 10), ("sahip ol", 12), ("duk", 11), ("larınız", 12), ("dan", 10), (" [evlenin]", 0)], "Fa-min ma malakat resumes the marriage alternative: then from what is possessed. Restore fa and the partitive/source relation, with the elided marry explicitly bracketed, rather than hiding the entire phrase at fa-min.")
    d("4:25:10", "Expose the resumed alternative and the partitive relation; the supplied marriage predicate is marked as an ellipsis explanation.")
    p("4:48", "other-things", [("başka", 10), ("sını", 9)], "Ma duna dhalika refers to what is other/less than that. Ma is a relative nominal object, not the English preposition from; expose its nominal/object ending without an ablative.")
    d("4:48:9", "Do not follow the isolated English from for Arabic ma; restore nominal-relative content in başkasını.")
    p("4:117", "restriction-conjunction", [("ve ", 7), ("yalnızca ", 9), ("çağırıyorlar", 8)], "Wa-in ... illa restricts invocation to the following object. Turkish yalnızca expresses the combined negative-exception force, so in needs no second negative suffix. Restore the overt conjunction at wa-in rather than hiding it inside context.")
    d("4:117:7", "Keep the valid positive-only restriction idiom, restoring the source conjunction and avoiding a second negation that would invert the meaning.")
    p("5:59", "question", [("hoşlanmıyor", 5), (" mu", 4), ("sunuz?", 5)], "Hal supplies the question particle; tanqimuna is naturally expressed by Turkish hoşlanmamak in this resentment context. The negative morphology belongs to that lexical paraphrase, not to an invented Arabic negation.")
    c("5:59", "content-introducer", {8: "diye"}, "An supplies the quoted/reason complement; the question particle is now exposed at hal, not duplicated at an.")
    d("5:59:4", "Restore the overt interrogative particle at hal without altering the resentment/reason relation.")
    p("5:60", "away-from-way", [("düz ", 26), ("yol", 27), ("dan", 25)], "An sawai al-sabil marks deviation from the even way. Attach the ablative to the final noun of the Turkish phrase, while showing the entire complement at the source preposition.")
    d("5:60:25", "Expose from the straight way with the proper complete noun-phrase scope.")
    p("5:63", "prevent-speech", [("günah ", 7), ("söylemeleri", 6), ("nden", 5)], "Yanhahum an qawlihim al-ithma prevents sinful saying. The Turkish menetmek frame governs a source complement söylemelerinden, not the inherited accusative sözlerini.")
    c("5:63", "coordinated-eating", {8: "ve yemelerinden"}, "The coordinated eating clause shares the same source complement of menetmek; retain consistent case across the two actions.")
    d("5:63:5 5:63:6", "Restore the action nominal and the source case required by the Turkish preventing construction.")
    d("5:76:3 7:81:5", "Retain the idiomatic replacement construction bırakıp plus its accusative complement. Min duni expresses exclusion/replacement jointly; an extra source ending would break this chosen Turkish verbal construction.", True)
    p("5:80", "anger-content", [("gazap et", 13), ("me", 12), ("si", 13)], "An sakhita introduces the explanatory content of the evil outcome. Turkish gazap etmesi is a nominal complement; restore its introducer instead of a context-only finite verb.")
    c("5:80", "anger-subject", {14: "Allah'ın"}, "The restored nominal clause takes its explicit subject in the Turkish genitive; this is the nominal complement's grammar, not a change to the divine agent.")
    d("5:80:12", "Restore nominal content under an and align the subject to that Turkish clause.")
    p("5:90", "work-category", [("işi", 11), ("ndendir", 10)], "Min amali al-shaytan classifies the abominations as of Satan's work. Turkish işindendir exposes the membership/source relation and predication; it does not make a mere occupational job claim.")
    c("5:90", "possessor", {12: "şeytanın"}, "Turkish işindendir requires its explicit possessor şeytanın; the relation is not left as an uninflected adjacent noun.")
    d("5:90:10", "Expose the work/category relation with a contextual Turkish nominal construction.")
    d("5:99:1 5:104:18 5:106:42 5:107:3", "Individually retain the inspected construction: ma ... illa is expressed by sadece, kana's conditional characterization is absorbed in olsa da mı, dha qurba is the kinship adjective akraba, and uthira ala anna is naturally a direct nominal discovery complement. No extra literal not, was, possessor or on word is required in those respective Turkish frames.", True)
    d("5:110:59 6:7:12 6:25:28 6:50:16 6:57:14 6:116:11 6:148:30 7:20:12 7:155:23 7:184:7 7:188:22 8:31:13 8:34:14", "Read the complete negative-exception restriction, not the negative particle alone. Turkish expresses its combined force either positively with ancak/sadece/sırf/yalnızca or with başka ... değil. Retain the context-only negative view where the restriction is already expressed by the paired exception; inserting a second independent negative would distort scope. This resolves that flag only, not every surrounding lexical choice.", True)
    p("5:112", "ability-question", [("gücü yeter", 8), (" mi?", 7)], "Hal is the question particle and yastatiu supplies ability. Restore the separate question view and standard mi spacing; this preserves the supplied Hafs reading rather than substituting a variant reading or a theological paraphrase.")
    d("5:112:7", "Expose the interrogative particle without changing the disciples' quoted question into a declarative claim about ability.")
    p("5:113", "truth-complement", [("bize doğru söyle", 11), ("diğ", 9), ("ini", 11)], "An introduces the content of knowing: that you spoke truth. Expose -diğ rather than copying the separate emphatic qad at the next position.")
    p("5:113", "among-witnesses", [("şahitler", 15), ("den", 14)], "Min al-shahidin expresses membership among witnesses. Restore şahitlerden and remove bizzat, which was unsupported at this source location.")
    d("5:113:9 5:113:14", "Restore the knowing complement and witness membership, keeping certainty at qad rather than an.")
    c("5:117", "command-content", {8: "[şöyle:]"}, "An introduces the content of the commanded imperative: worship Allah. An explanatory content marker avoids hiding the imperative at both an and u'budu.")
    d("5:117:8", "Separate the explanatory command introducer from the imperative while preserving its divine addressee.")
    d("6:5:10 6:10:11 6:94:28 6:138:25 6:157:34 7:9:9 7:43:35 7:53:29 7:137:23 7:163:26 7:165:17 9:95:17", "Individually read the kana plus verbal/relative clause in its retrospective context. Turkish already uses a nominalized or habitual expression (for example ettikleri, sandığınız, yapageldiği) rather than a separate finite copula. Retain the contextual kana view; adding an independent idiler would create a second predicate. The surrounding Arabic past/habitual scope remains recorded as evidence.", True)
    c("6:29", "life-pronoun", {2: "(o [hayat])", 3: "o [hayat]"}, "Hiya is a feminine singular pronoun for life, not they. Restore singular reference while retaining the following exception/worldly-life restriction.")
    d("6:29:2", "Retain the negative-exception construction but correct the singular pronoun in its contextual view.")
    p("6:31", "neglect-relative", [("kusur et", 16), ("tiğ", 15), ("imizden", 16)], "Ma farratna is the neglect for which regret is expressed. Restore its nominal-relative contribution rather than copying the whole nominal kusurlarımızdan. The inherited dolayı frame retains its required contextual ablative in the inflected verbal view.")
    d("6:31:15", "Restore the relative content of the regretted neglect; the preceding ala supplies dolayı in the inherited frame.")
    d("6:35:2", "Retain the conditional past ağır geldiyse: kana's support is absorbed in the Turkish inflected predicate of the in clause. No separate existence noun or completed past auxiliary is needed.", True)
    p("6:48", "negative-conjunction", [("ve ", 1), ("biz gönder", 2), ("me", 1), ("yiz", 2)], "Wa-ma nursilu includes and plus negation; restore the overt conjunction while retaining the first-person plural sending predicate.")
    d("6:48:1 6:48:2", "Retain the negative sending predicate and restore wa at the negative source word; the following exception preserves the messenger purpose.")
    p("6:89", "not-disbelieving", [("bunları ", 16), ("inkar et", 17), ("me", 15), ("yen", 17)], "Laysu biha bikafirina characterizes the entrusted people as not disbelieving in these things. Restore the pronominal complement at biha, negation at laysu and the disbelieving characterization at kafirina, rather than fragmentary inkar / bunları etmeyecek.")
    d("6:89:16", "Restore the displaced pronominal complement and the negative characterization, without importing a new unsupported future tense.")
    d("6:91:13 6:99:26", "Retain the inspected nominal frames: min shayin under negation has an unpronounced separate surface beside bir şey, and min anab identifies the grape variety of gardens, naturally üzüm bahçeleri. A physical-origin suffix would change the intended Turkish construction.", True)
    p("6:92", "before-it", [("kendisin", 8), ("den önce", 7), ("kini", 6)], "Alladhi bayna yadayhi is the familiar idiom what preceded it, not what lies physically between its hands. Restore the anterior reference and expose its relative object ending. The pronoun and before relation are functional components of the full Arabic idiom.")
