    d("6:135:12", "Restore the for-whom relation while retaining the subsequent fate-of-the-abode expression.")
    p("6:136", "relative-share", [("ve ", 22), ("ol", 23), ("an", 22)], "Wa-ma kana lillahi is and what was for Allah. Restore the conjunction and nominal relative ending rather than two context-only olan copies.")
    p("6:136", "bad-judgment", [("hüküm ver", 31), ("iş", 30), ("leri", 31)], "Ma yahkumuna is the judgment/action condemned as bad. Hüküm verişleri exposes nominalization instead of an unexplained finite hüküm veriyorlar at ma.")
    c("6:136", "bad-predication", {29: "ne kötüdür"}, "Saa expresses an evaluative badness predicate, naturally ne kötüdür before the nominalized judgment.")
    d("6:136:22 6:136:30", "Restore the two nominal-relative constructions, distinguishing them from negation.")
    d("6:143:6 6:143:7 6:144:4 6:144:5", "Retain the explicitly inspected coordinated class selections: ve keçilerden / ve sığırlardan correctly expose the conjunction, partitive suffix and animal noun without duplicating the quantity two.", True)
    d("6:148:9", "The forefathers clause is coordinated under the preceding counterfactual negative ortak koşmazdık; Turkish babalarımız da inherits that elliptical negation. Do not invent an independent finite verb or make it a positive claim.", True)
    p("6:148", "earlier-deniers", [("onlar", 19), ("dan", 18), (" önce ol", 19), ("anlar", 17)], "Alladhina min qablihim identifies those before them; expose its plural relative contribution. The neighboring kadhdhaba is a finite denial predicate, not an additional relative noun.")
    c("6:148", "denial-predicate", {16: "yalanladı"}, "Kadhdhaba is the finite perfect verb; restore it instead of the inherited nominal yalanlayanlar, now that the subject-relative construction is explicit.")
    d("6:148:17", "Restore the relative subjects and finite denial predicate at their distinct Arabic positions.")
    p("6:150", "prohibition-complement", [("yasakla", 8), ("dığ", 6), ("ına", 8)], "Anna introduces the testified content that Allah prohibited it. Expose -dığ at anna, leaving Allah'ın as the Turkish nominal clause's subject.")
